INSERT INTO `WITH so_line_if AS (
    SELECT
        a.orig_sys_document_ref,
        a.orig_sys_line_ref,
        a.sales_order_no,
        a.order_line_id,
        a.order_header_id,
        a.cust_po_no,
        a.cust_po_date,
        a.model_code,
        a.bill_to_customer_code,
        a.unit_selling_price,
        a.line_status_code,
        a.booked_date,
        a.pick_release_date,
        a.actual_shipment_date,
        a.request_shipping_date,
        a.line_no,
        ROW_NUMBER() OVER (
            PARTITION BY a.orig_sys_document_ref, a.orig_sys_line_ref
            ORDER BY a.transfer_date DESC
        ) AS rn
    FROM xxomds_so_line_if a
    WHERE a.order_category_code = 'ORDER'
      AND a.subinventory_code   = 'GOODSET'
      AND a.ship_to_customer_code IN (
          'US074178-LMD-S', 'US074178P-LMD-S', 'US074178E-LMD-S')
      AND a.ordered_date BETWEEN '2025-01-05' AND '2026-01-15'
),

so_line_final AS (
    SELECT * FROM so_line_if WHERE rn = 1 AND line_status_code <> 'CANCELLED'
),

so_line_if_hold AS (
    SELECT
        c.sales_order_no,
        c.line_no,
        c.transfer_date,
        ROW_NUMBER() OVER (
            PARTITION BY c.orig_sys_document_ref, c.orig_sys_line_ref
            ORDER BY c.transfer_date ASC
        ) AS rn2
    FROM xxomds_so_line_if c
    INNER JOIN so_line_final slf
        ON c.orig_sys_document_ref = slf.orig_sys_document_ref
       AND c.orig_sys_line_ref     = slf.orig_sys_line_ref
    WHERE c.order_category_code  = 'ORDER'
      AND c.subinventory_code    = 'GOODSET'
      AND c.ship_to_customer_code IN (
          'US074178-LMD-S', 'US074178P-LMD-S', 'US074178E-LMD-S')
      AND c.line_status_code     = 'BOOKED'
      AND c.line_status_code2    = 'BACK'
      AND c.transfer_date        > '2025-11-15'
),

order_hold_s_if AS (
    SELECT
        d.order_no,
        d.order_line_id,
        SUBSTRING_INDEX(
            GROUP_CONCAT(d.hold_name ORDER BY d.order_hold_id SEPARATOR '|'),
            '|', 1
        ) AS first_hold_name,
        GROUP_CONCAT(IFNULL(d.hold_name, 'NULL')
            ORDER BY d.order_hold_id SEPARATOR '|') AS hold_names,
        GROUP_CONCAT(IFNULL(d.hold_date, 'NULL')
            ORDER BY d.order_hold_id SEPARATOR '|') AS hold_dates
    FROM xxomds_order_hold_s_if d
    WHERE d.transfer_date > '2025-11-15'
    GROUP BY d.order_no, d.order_line_id
),

ifr_tms_edi_214_pod_hd AS (
    SELECT
        f.cust_sales_order_no,
        f.attribute1 AS model,
        MAX(CASE WHEN f.event_cd='AG' AND f.pod_desc='NS'
            THEN CONCAT_WS('-', f.event_cd, f.pod_desc) END) AS scheduled_pod_desc,
        MAX(CASE WHEN f.event_cd='AG' AND f.pod_desc='NS'
            THEN f.pod_dt END)                               AS scheduled_pod_dt,
        MAX(CASE WHEN f.event_cd='AG' AND f.pod_desc='CS'
            THEN CONCAT_WS('-', f.event_cd, f.pod_desc) END) AS cust_updated_pod_desc,
        MAX(CASE WHEN f.event_cd NOT IN ('AG','X4','AM','D1','X1')
             OR  (f.event_cd='AG' AND f.pod_desc NOT IN ('NS','CS'))
            THEN CONCAT_WS('-', f.event_cd, f.pod_desc) END) AS updated_pod_desc,
        MAX(CASE WHEN f.event_cd='X4' AND f.pod_desc='NS'
            THEN f.pod_dt END)                               AS received_agent_pod_dt,
        RIGHT(MAX(CASE WHEN f.event_cd='X4' AND f.pod_desc='NS'
            THEN f.pod_dt END), 10)                          AS last_received_agent_pod_dt,
        MAX(CASE WHEN f.event_cd='AM' AND f.pod_desc='NS'
            THEN f.pod_dt END)                               AS out_delivery_pod_dt,
        MAX(CASE WHEN f.event_cd IN ('D1','X1') AND f.pod_desc='NS'
            THEN f.pod_dt END)                               AS completed_pod_dt,
        RIGHT(MAX(CASE WHEN f.event_cd IN ('D1','X1') AND f.pod_desc='NS'
            THEN f.pod_dt END), 10)                          AS last_completed_pod_dt
    FROM xxtms_ifr_tms_edi_214_pod_hd f
    WHERE f.transfer_date > '2025-11-15'
      AND (f.event_cd, f.pod_desc) IN (
          ('AG','NS'), ('AG','CS'), ('AG','IT'), ('AG','DC'),
          ('AG','LM'), ('AG','WW'), ('X4','NS'), ('AM','NS'),
          ('D1','NS'), ('X1','NS'))
    GROUP BY f.cust_sales_order_no, f.attribute1
),

inf_wms_status AS (
    SELECT
        h.order_no,
        h.order_line_id,
        MAX(CASE WHEN h.status = '02' THEN h.interface_date END) AS load_plan_date
    FROM tmr_inf_wms_status h
    WHERE h.interface_date > '2025-11-15'
    GROUP BY h.order_no, h.order_line_id
),

omv_base AS (
    SELECT
        orig_sys_document_ref,
        orig_sys_line_ref,
        original_header_id,
        original_line_id,
        operation_code,
        process_status_code,
        subinventory_code,
        transfer_date,
        request_date
    FROM xxomv_order_if
    WHERE transfer_date > '2025-11-15'
      AND process_status_code = 'S'
)

SELECT
    slf.sales_order_no,
    slf.order_line_id,
    slf.cust_po_no,
    slf.model_code,
    slf.bill_to_customer_code,
    slf.unit_selling_price,
    slf.line_status_code,
    CAST(slf.cust_po_date AS DATE)               AS order_date,
    CAST(slf.booked_date AS DATE)                AS gerp_booked_date,
    CAST(slih.transfer_date AS DATE)             AS back_order_date,
    CAST(slf.pick_release_date AS DATE)          AS pick_release_date,
    CAST(iws.load_plan_date AS DATE)             AS load_plan_date,
    CAST(slf.actual_shipment_date AS DATE)       AS actual_shipment_date,
    CAST(tms.last_received_agent_pod_dt AS DATE) AS hub_received_dt,
    tms.out_delivery_pod_dt,
    CAST(tms.last_completed_pod_dt AS DATE)      AS delivered_dt,
    DATE_FORMAT(xoi.request_date, '%Y-%m-%d')    AS rad1,
    DATE_FORMAT(xoi_upd.request_date, '%Y-%m-%d') AS rad2,
    tms.scheduled_pod_dt                         AS rad3_raw,
    ohsi.first_hold_name,
    ohsi.hold_names,
    ohsi.hold_dates,
    tms.scheduled_pod_desc,
    tms.scheduled_pod_dt,
    tms.cust_updated_pod_desc,
    tms.updated_pod_desc,
    tms.received_agent_pod_dt,
    tms.out_delivery_pod_dt                      AS out_delivery_pod_dt_raw,
    tms.completed_pod_dt,
    slf.request_shipping_date
FROM omv_base xoi
INNER JOIN so_line_final slf
    ON xoi.orig_sys_document_ref = slf.orig_sys_document_ref
   AND xoi.orig_sys_line_ref     = slf.orig_sys_line_ref
   AND xoi.subinventory_code IS NULL
LEFT JOIN omv_base xoi_upd
    ON slf.order_header_id       = xoi_upd.original_header_id
   AND slf.order_line_id         = xoi_upd.original_line_id
   AND xoi_upd.operation_code    = 'UPDATE'
LEFT JOIN (SELECT * FROM so_line_if_hold WHERE rn2 = 1) slih
    ON slf.sales_order_no = slih.sales_order_no
   AND slf.line_no        = slih.line_no
LEFT JOIN order_hold_s_if ohsi
    ON slf.sales_order_no = ohsi.order_no
   AND slf.order_line_id  = ohsi.order_line_id
LEFT JOIN ifr_tms_edi_214_pod_hd tms
    ON slf.sales_order_no = tms.cust_sales_order_no
   AND slf.model_code     = tms.model
LEFT JOIN inf_wms_status iws
    ON slf.sales_order_no = iws.order_no
   AND slf.order_line_id  = iws.order_line_id
ORDER BY slf.cust_po_date, slf.orig_sys_document_ref` (sales_order_no,order_line_id,cust_po_no,model_code,bill_to_customer_code,unit_selling_price,line_status_code,order_date,gerp_booked_date,back_order_date,pick_release_date,load_plan_date,actual_shipment_date,hub_received_dt,out_delivery_pod_dt,delivered_dt,rad1,rad2,scheduled_pod_dt,first_hold_name,hold_names,hold_dates,scheduled_pod_desc,scheduled_pod_dt,cust_updated_pod_desc,updated_pod_desc,received_agent_pod_dt,out_delivery_pod_dt,completed_pod_dt,request_shipping_date) VALUES
